'use strict';

// MODULES //

var tape = require( 'tape' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var isNonNegativeInteger = require( '@stdlib/math/base/assert/is-nonnegative-integer' );
var isUint32Array = require( '@stdlib/assert/is-uint32array' );
var xorshift32 = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof xorshift32, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the main export is a method to generate normalized pseudorandom numbers', function test( t ) {
	t.strictEqual( typeof xorshift32.normalized, 'function', 'has method' );
	t.end();
});

tape( 'attached to the main export is a method to create a xorshift32 pseudorandom number generator', function test( t ) {
	t.strictEqual( typeof xorshift32.factory, 'function', 'has method' );
	t.end();
});

tape( 'attached to the main export is a method to serialize a pseudorandom number generator as JSON', function test( t ) {
	t.strictEqual( typeof xorshift32.toJSON, 'function', 'has method' );
	t.end();
});

tape( 'attached to the main export is the generator name', function test( t ) {
	t.strictEqual( xorshift32.NAME, 'xorshift32', 'has property' );
	t.end();
});

tape( 'attached to the main export is the minimum possible generated number', function test( t ) {
	t.strictEqual( xorshift32.MIN, 1, 'has property' );
	t.end();
});

tape( 'attached to the main export is the maximum possible generated number', function test( t ) {
	t.strictEqual( xorshift32.MAX, UINT32_MAX, 'has property' );
	t.end();
});

tape( 'attached to the main export is the generator seed', function test( t ) {
	t.strictEqual( isUint32Array( xorshift32.seed ), true, 'has property' );
	t.end();
});

tape( 'attached to the main export is the generator seed length', function test( t ) {
	t.strictEqual( typeof xorshift32.seedLength, 'number', 'has property' );
	t.end();
});

tape( 'attached to the main export is the generator state', function test( t ) {
	t.strictEqual( isUint32Array( xorshift32.state ), true, 'has property' );
	t.end();
});

tape( 'attached to the main export is the generator state length', function test( t ) {
	t.strictEqual( typeof xorshift32.stateLength, 'number', 'has property' );
	t.end();
});

tape( 'attached to the main export is the generator state size', function test( t ) {
	t.strictEqual( typeof xorshift32.byteLength, 'number', 'has property' );
	t.end();
});

tape( 'the function returns pseudorandom unsigned 32-bit integers on the interval [1, 2^32-1]', function test( t ) {
	var v;
	var i;
	for ( i = 0; i < 1e3; i++ ) {
		v = xorshift32();
		t.strictEqual( typeof v, 'number', 'returns expected value' );
		t.strictEqual( isNonNegativeInteger( v ), true, 'returns a non-negative integer' );
		t.strictEqual( v >= 1 && v <= UINT32_MAX, true, 'returns an integer between 1 and 2^32-1 (inclusive)' );
	}
	t.end();
});

tape( 'the function never returns zero (zero is a fixed point of the xorshift32 recurrence)', function test( t ) {
	var v;
	var i;
	for ( i = 0; i < 1e3; i++ ) {
		v = xorshift32();
		t.notEqual( v, 0, 'does not return zero' );
	}
	t.end();
});

tape( 'the `normalized` method returns pseudorandom numbers on the interval (0, 1]', function test( t ) {
	var v;
	var i;
	for ( i = 0; i < 1e3; i++ ) {
		v = xorshift32.normalized();
		t.strictEqual( typeof v, 'number', 'returns expected value' );
		t.strictEqual( v > 0.0 && v <= 1.0, true, 'returns a number strictly between 0 (exclusive) and 1 (inclusive)' );
	}
	t.end();
});

tape( 'attached to the `normalized` method is the generator name', function test( t ) {
	t.strictEqual( xorshift32.normalized.NAME, 'xorshift32', 'has property' );
	t.end();
});

tape( 'attached to the `normalized` method is the minimum possible generated number', function test( t ) {
	t.strictEqual( xorshift32.normalized.MIN, 1.0 / UINT32_MAX, 'has property' );
	t.end();
});

tape( 'attached to the `normalized` method is the maximum possible generated number', function test( t ) {
	t.strictEqual( xorshift32.normalized.MAX, 1.0, 'has property' );
	t.end();
});

tape( 'attached to the `normalized` method is the generator seed', function test( t ) {
	t.strictEqual( isUint32Array( xorshift32.normalized.seed ), true, 'has property' );
	t.end();
});

tape( 'attached to the `normalized` method is the generator seed length', function test( t ) {
	t.strictEqual( typeof xorshift32.normalized.seedLength, 'number', 'has property' );
	t.end();
});

tape( 'attached to the `normalized` method is the generator state', function test( t ) {
	t.strictEqual( isUint32Array( xorshift32.normalized.state ), true, 'has property' );
	t.end();
});

tape( 'attached to the `normalized` method is the generator state length', function test( t ) {
	t.strictEqual( typeof xorshift32.normalized.stateLength, 'number', 'has property' );
	t.end();
});

tape( 'attached to the `normalized` method is the generator state size', function test( t ) {
	t.strictEqual( typeof xorshift32.normalized.byteLength, 'number', 'has property' );
	t.end();
});

tape( 'attached to the `normalized` method is a method to serialize a pseudorandom number generator as JSON', function test( t ) {
	t.strictEqual( typeof xorshift32.normalized.toJSON, 'function', 'has method' );
	t.end();
});

tape( 'the generator supports setting the generator state', function test( t ) {
	var state;
	var arr;
	var i;

	// Move to a future state...
	for ( i = 0; i < 100; i++ ) {
		xorshift32();
	}
	// Capture the current state:
	state = xorshift32.state;

	// Move to a future state...
	arr = [];
	for ( i = 0; i < 100; i++ ) {
		arr.push( xorshift32() );
	}
	// Set the state:
	xorshift32.state = state;

	// Replay previously generated values...
	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( xorshift32(), arr[ i ], 'returns expected value. i: '+i+'.' );
	}
	t.end();
});

tape( 'the generator supports setting the generator state (normalized)', function test( t ) {
	var state;
	var arr;
	var i;

	// Move to a future state...
	for ( i = 0; i < 100; i++ ) {
		xorshift32.normalized();
	}
	// Capture the current state:
	state = xorshift32.state;

	// Move to a future state...
	arr = [];
	for ( i = 0; i < 100; i++ ) {
		arr.push( xorshift32.normalized() );
	}
	// Set the state:
	xorshift32.state = state;

	// Replay previously generated values...
	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( xorshift32.normalized(), arr[ i ], 'returns expected value. i: '+i+'.' );
	}
	t.end();
});

tape( 'the generator supports setting the generator state via the `normalized` property', function test( t ) {
	var state;
	var arr;
	var i;

	// Move to a future state...
	for ( i = 0; i < 100; i++ ) {
		xorshift32.normalized();
	}
	// Capture the current state:
	state = xorshift32.normalized.state;

	// Move to a future state...
	arr = [];
	for ( i = 0; i < 100; i++ ) {
		arr.push( xorshift32.normalized() );
	}
	// Set the state:
	xorshift32.normalized.state = state;

	// Replay previously generated values...
	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( xorshift32.normalized(), arr[ i ], 'returns expected value. i: '+i+'.' );
	}
	t.end();
});

tape( 'the `toJSON` method returns an object with expected properties', function test( t ) {
	var o = xorshift32.toJSON();
	t.strictEqual( typeof o, 'object', 'returns an object' );
	t.strictEqual( o.type, 'PRNG', 'has expected type property' );
	t.strictEqual( o.name, xorshift32.NAME, 'has expected name property' );
	t.strictEqual( typeof o.state, 'object', 'has expected state property' );
	t.ok( Array.isArray( o.params ), 'has expected params property' );
	t.end();
});
